<?php require __DIR__.'/../bootstrap.php'; require_admin(); if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: dashboard.php');exit;}check_csrf();$id=(int)($_POST['id']??0);$status=$_POST['status']??'new';$severity=$_POST['severity']??'medium';if(!in_array($status,['new','triaged','in_progress','resolved','closed'],true))$status='new';if(!in_array($severity,['low','medium','high','critical'],true))$severity='medium';$st=db()->prepare('UPDATE bug_reports SET status=?,severity=?,admin_note=? WHERE id=?');$st->execute([$status,$severity,trim($_POST['admin_note']??''),$id]);flash('Report updated.');header('Location: view.php?id='.$id);
